-- F2c of the system-agnostic campaigns (odd/tasks/system-agnostic.md, S9, S10): every campaign gets the D&D 5e character
-- sheet as data (`system_profile.sheet`, the optional key F2b taught the validator to carry), and so does every campaign
-- created from now on. Nothing reads the sheet yet, so there is no visible change; the renderer and the editor come in F4/F5.
--
--   * The literal below is the TypeScript preset (src/campaign/system/sheet/dnd5eSheet.ts) serialised;
--     dnd5eSheetMigration.test.ts fails if the two ever differ.
--   * The backfill only touches campaigns that have no sheet, and only adds that key.
--
-- Rollback (manual, not part of the migration):
--   update public.campaigns set system_profile = system_profile - 'sheet';
--   and set the column default back to the document of 20261027120000 (the same literal without the sheet).

------------------------------------------------------------------------------
-- Default for new campaigns
------------------------------------------------------------------------------
alter table public.campaigns
  alter column system_profile set default $profile${
    "version": 1,
    "character": {
      "builtins": {
        "clase": {"enabled": true, "label": "Clase"},
        "raza": {"enabled": true, "label": "Raza"},
        "nivel": {"enabled": true, "label": "Nivel", "min": 1, "max": 20}
      },
      "sections": {
        "stats": true, "habilidades": true, "ataques": true, "hechizos": true, "recursos": true,
        "equipo": true, "rasgos": true, "narrativa": true, "apariencia": true
      }
    },
    "currency": {
      "enabled": true,
      "denominations": [
        {"key": "pp", "label": "platino"},
        {"key": "gp", "label": "oro"},
        {"key": "ep", "label": "electrum"},
        {"key": "sp", "label": "plata"},
        {"key": "cp", "label": "bronce"}
      ]
    },
    "modules": {"juegos": true, "sesion_en_vivo": true, "mapas": true, "calendario": true}
  }$profile$::jsonb
    || jsonb_build_object('sheet', $dnd5e_sheet${"categories":[{"key":"identidad_dnd","label":"Identidad D&D","sections":[{"key":"general","label":"General","items":[{"kind":"field","key":"trasfondo_dnd","label":"Trasfondo D&D","type":"short","editableBy":"player"},{"kind":"field","key":"alineamiento","label":"Alineamiento","type":"short","editableBy":"player"},{"kind":"field","key":"experiencia","label":"Experiencia (XP)","type":"number","editableBy":"dm","min":0}],"blocks":[{"key":"b_general","mode":"tile","items":["trasfondo_dnd","alineamiento","experiencia"]}]}]},{"key":"mecanicas","label":"Mecánicas","sections":[{"key":"stats","label":"Atributos y combate","items":[{"kind":"table","type":"stat","key":"tabla_stats","label":"Atributos","rows":[{"key":"stat_str","label":"FUE","modifier":"floor(({valor} - 10) / 2)","editableBy":"dm"},{"key":"stat_dex","label":"DES","modifier":"floor(({valor} - 10) / 2)","editableBy":"dm"},{"key":"stat_con","label":"CON","modifier":"floor(({valor} - 10) / 2)","editableBy":"dm"},{"key":"stat_int","label":"INT","modifier":"floor(({valor} - 10) / 2)","editableBy":"dm"},{"key":"stat_wis","label":"SAB","modifier":"floor(({valor} - 10) / 2)","editableBy":"dm"},{"key":"stat_cha","label":"CAR","modifier":"floor(({valor} - 10) / 2)","editableBy":"dm"}]},{"kind":"field","key":"dado_golpe","label":"Dado de golpe","type":"short","editableBy":"dm","default":""},{"kind":"field","key":"dados_disponibles","label":"Dados de golpe disponibles","type":"number","editableBy":"dm","min":0,"default":0},{"kind":"field","key":"stat_hp","label":"HP máx.","type":"number","editableBy":"dm","min":0},{"kind":"field","key":"stat_hp_current","label":"HP actual","type":"number","editableBy":"dm","min":0},{"kind":"field","key":"stat_hp_temp","label":"HP temporal","type":"number","editableBy":"dm","min":0},{"kind":"field","key":"stat_ac","label":"AC","type":"number","editableBy":"dm","min":0},{"kind":"field","key":"stat_ac_temp","label":"AC temporal","type":"number",